import cats.Eval

def isEven(n: Int): Eval[Boolean] =
  Eval.defer(if (n == 0) Eval.now(true) else isOdd(n - 1))
def isOdd(n: Int): Eval[Boolean] =
  Eval.defer(if (n == 0) Eval.now(false) else isEven(n - 1))

isEven(1_000_000).value    // trampolined, stack-safe
